11	export function NameSettingForm({ initialName }: { initialName: string }) {
12	  const [name, setName] = React.useState(initialName);
13	  const [pending, startTransition] = useTransition();
14	  const [error, setError] = React.useState<string | null>(null);
15	  const { toast } = useToast();
16	
17	  function save() {
18	    setError(null);
19	    startTransition(async () => {
20	      const res = await updateProfileName(name);
21	      if (!res.ok) {
22	        setError(res.error ?? t("auth.errorGeneric"));
23	        return;
24	      }
25	      toast(t("account.nameSaved"), "success");
26	    });
27	  }
28	
29	  return (
30	    <div className="flex flex-wrap items-end gap-3">
31	      <Field label={t("account.yourNameLabel")} error={error ?? undefined} required>
32	        {(p) => (
33	          <Input
34	            {...p}
35	            value={name}
36	            onChange={(e) => setName(e.target.value)}
37	            maxLength={120}
38	            autoComplete="name"
39	          />
40	        )}
41	      </Field>
42	      <Button onClick={save} disabled={pending}>
43	        {pending ? t("ui.loading") : t("account.saveName")}
44	      </Button>
45	    </div>
46	  );
47	}
