3	import * as React from "react";
4	import { useRouter } from "next/navigation";
5	import { Star, CircleAlert } from "lucide-react";
6	import { Button } from "@/components/ui/Button";
7	import { Field, Input } from "@/components/ui/Field";
8	import { Chip } from "@/components/ui/Chip";
9	import { submitReview } from "@/app/(customer)/session/actions";
10	import { formatCents } from "@/lib/format";
11	import { t } from "@/lib/i18n";
12	
13	const TIP_PRESETS = [0, 200, 500, 1000];
14	
15	export function RatingTipForm({
16	  sessionId,
17	  providerId,
18	}: {
19	  sessionId: string;
20	  providerId: string;
21	}) {
22	  const router = useRouter();
23	  const [rating, setRating] = React.useState(0);
24	  const [tipCents, setTipCents] = React.useState(0);
25	  const [customTip, setCustomTip] = React.useState("");
26	  const [comment, setComment] = React.useState("");
27	  const [submitting, setSubmitting] = React.useState(false);
28	  const [error, setError] = React.useState<string | null>(null);
29	
30	  function pickTip(cents: number) {
31	    setTipCents(cents);
32	    setCustomTip("");
33	  }
34	
35	  async function onSubmit() {
36	    if (rating < 1) {
37	      setError(t("summary.chooseRating"));
38	      return;
39	    }
40	    setSubmitting(true);
41	    setError(null);
42	    const finalTip = customTip
43	      ? Math.max(0, Math.round(Number(customTip) * 100) || 0)
44	      : tipCents;
45	    const res = await submitReview({
46	      sessionId,
47	      providerId,
48	      rating,
49	      comment: comment.trim() || undefined,
50	      tipCents: finalTip,
51	    });
52	    if (res.error) {
53	      setError(res.error);
54	      setSubmitting(false);
55	      return;
56	    }
57	    router.refresh();
58	  }
59	
60	  return (
61	    <div className="flex flex-col gap-6">
62	      {error ? (
63	        <p
64	          role="alert"
65	          className="flex items-start gap-2 rounded-card border-l-4 border-alert bg-alert-tint px-4 py-3 text-base"
66	        >
67	          <CircleAlert size={20} aria-hidden="true" className="mt-0.5 text-alert" />
68	          {error}
69	        </p>
70	      ) : null}
71	
72	      <fieldset className="flex flex-col gap-3">
73	        <legend className="text-h3">{t("summary.rateHeading")}</legend>
74	        <div role="radiogroup" className="flex gap-1.5">
75	          {[1, 2, 3, 4, 5].map((n) => (
76	            <button
77	              key={n}
78	              type="button"
79	              role="radio"
80	              aria-checked={rating === n}
81	              aria-label={t("summary.starLabel", { n })}
82	              onClick={() => setRating(n)}
83	              className="rounded-sm p-1"
84	            >
85	              <Star
86	                size={40}
87	                strokeWidth={2}
88	                aria-hidden="true"
89	                className={n <= rating ? "fill-accent text-accent" : "text-border-strong"}
90	              />
91	            </button>
92	          ))}
93	        </div>
94	      </fieldset>
95	
96	      <fieldset className="flex flex-col gap-3">
97	        <legend className="text-h3">{t("summary.tipHeading")}</legend>
98	        <p className="text-base text-ink-soft">{t("summary.tipHint")}</p>
99	        <div className="flex flex-wrap gap-2.5">
100	          {TIP_PRESETS.map((cents) => (
101	            <Chip
102	              key={cents}
103	              selected={!customTip && tipCents === cents}
104	              onClick={() => pickTip(cents)}
105	            >
